public class Solution {
    private static long mdc(long a, long b) { while (b != 0) { long t = a % b; a = b; b = t; } return a; }

    // r = C(n-k+i, i) a cada passo. Para multiplicar por num e dividir por i sem estourar,
    // cancela o MDC de i com r e com num antes da multiplicação.
    static long binomial(int n, int k) {
        if (k < 0 || k > n) return 0;
        k = Math.min(k, n - k);
        long r = 1;
        for (int i = 1; i <= k; i++) {
            long num = n - k + i, den = i;
            long g = mdc(r, den);
            r /= g;
            den /= g;
            num /= den; // agora den divide num (r·num/den é inteiro e mdc(r, den) = 1)
            r *= num;
        }
        return r;
    }

    static long catalan(int n) {
        return binomial(2 * n, n) / (n + 1);
    }
}

