import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;

class SolutionTest {
    private static BigInteger exato(int n, int k) {
        BigInteger r = BigInteger.ONE;
        for (int i = 1; i <= k; i++) r = r.multiply(BigInteger.valueOf(n - k + i)).divide(BigInteger.valueOf(i));
        return r;
    }

    @Test void pequenos() {
        assertEquals(10, Solution.binomial(5, 2));
        assertEquals(1, Solution.binomial(7, 0));
        assertEquals(1, Solution.binomial(7, 7));
        assertEquals(0, Solution.binomial(3, 5));
        assertEquals(0, Solution.binomial(3, -1));
    }

    @Test void todosAte66() {
        for (int n = 0; n <= 66; n++)
            for (int k = 0; k <= n; k++)
                assertEquals(exato(n, k).longValueExact(), Solution.binomial(n, k), "C(" + n + "," + k + ")");
    }

    @Test void catalan() {
        long[] esperado = {1, 1, 2, 5, 14, 42, 132, 429, 1430, 4862};
        for (int n = 0; n < esperado.length; n++) assertEquals(esperado[n], Solution.catalan(n));
        assertEquals(exato(66, 33).divide(BigInteger.valueOf(34)).longValueExact(), Solution.catalan(33));
    }
}
